import React, { useState } from "react";
import Navbar from "./Navbar";

export default function App() {
  const [page, setPage] = useState("home");
  const [user, setUser] = useState(null);

  const onNavigate = (newPage) => {
    setPage(newPage);
  };

  const onLogout = () => {
    setUser(null);
    setPage("home");
  };

  return (
    <div>
      <Navbar onNavigate={onNavigate} onLogout={onLogout} user={user} />

      {page === "home" && <h1>Home Page</h1>}
      {page === "login" && <h1>Login Page</h1>}
      {page === "register" && <h1>Register Page</h1>}
      {page === "dashboard" && <h1>User Dashboard</h1>}
    </div>
  );
}
